mapper.select:
SELECT FROM sys95_manual INNER JOIN sys10_file ON sys10_parent_id = sys95_manual_id WHERE sys95_manual_type LIKE #{manualType} AND CONCAT(sys10_file_nm, sys95_note) ILIKE #{searchText}
AND COALESCE(sys95_public_yn, 'false') = 'true'
ORDER BY sys10_reg_date DESC

mapper.update:
UPDATE sys95_manual
   SET sys95_manual_type = #{r.manualType}
     , sys95_public_yn = #{r.publicYn}
     , sys95_note = #{r.note}
 WHERE sys95_manual_id = #{r.manualId}

mapper.delete:
DELETE FROM sys95_manual
 WHERE sys95_manual_id IN
#{id}

mapper.select:
SELECT count(*)
  FROM sys95_manual
 WHERE sys95_company_id  = #{companyId}
   AND sys95_manual_type = #{manualType}
